import axios from 'axios';

const API_BASE_URL = 'http://localhost:8080/api'; // ✅ Make sure this is your backend URL

export const createBooking = async (bookingData, userId, parkingSlotId) => {
  const url = `${API_BASE_URL}/bookings?userId=${userId}&parkingSlotId=${parkingSlotId}`;
  return axios.post(url, bookingData);
};
